const banks={fund1:[],fund3:[]};
function rows(subject,source,block){
  for(const line of block.trim().split('\n')){
    const fields=line.split('|');
    if(fields.length!==12)throw new Error(`Invalid governance row ${fields[1]}: ${fields.length}`);
    const [code,topic,article,stem,...pairs]=fields;
    const sequence=banks[subject].length+1, answer=(sequence-1)%4;
    const choices=Array.from({length:4},(_,i)=>[pairs[i*2],pairs[i*2+1]]);
    for(let i=0;i<answer;i++)choices.unshift(choices.pop());
    const officialChapter=Number(code.split('.')[0]);
    banks[subject].push({id:`${subject}-expansion-gov-${String(sequence).padStart(4,'0')}`,chapter:officialChapter+5,lessonId:`${subject}-syllabus-${officialChapter}`,scope:code.slice(0,code.lastIndexOf('.')),outlineCodes:[code],topic,conceptIds:[topic],type:'single',stem,options:choices.map(x=>x[0]),rationales:choices.map(x=>x[1]),answer,explanation:choices[answer][1],source,referenceSection:`${EXPANSION_FUND_GOVERNANCE_SOURCES[source].title.split(" · ")[1]} · ${article}`,sourceKind:'original',origin:'原创模拟 · 法规治理情景 · 非真题',difficulty:'applied',editorialBatch:'2026-10-14-expansion',reviewedAt:'2026-10-14',reviewNote:'AI辅助逐题原创；已由另一轮AI内容复核并核对列明官方来源。大纲映射不表示充分覆盖；虚构教学案例，不是官方真题或人类专家审定。'});
  }
}

// Batch A1: public fund property, service boundaries and governance decisions.
rows('fund1','expansionGovFundLaw',`
2.2.a|基金投资附随收益的归属|第五条第二款、第三款|甲管理人为基金持股领取了证券发行人的赔偿款，财务部拟将款项作为公司营业外收入。应如何处理？|计入该基金财产并与公司财产分开|赔偿源于基金财产的管理运用，应归入基金财产，不能因款项由管理人领取而改变归属。|管理人领取即可计入公司收入|收款主体不等于财产最终权利人，管理人代基金领取不能把受托所得变成固有收入。|按管理人与基金各半分配|基金法没有将此类附随收益各半分配的规则，任意分成会侵占应归基金的财产。|先抵扣管理公司经营亏损再返还|公司经营亏损应由公司自身承担，不能擅自用独立的基金收益弥补公司亏损。
2.2.a|基金自身债务与强制执行边界|第七条|法院依法执行基金财产本身承担的到期债务，管理人以基金财产独立为由主张任何债权人均不得执行。应如何纠正？|独立财产保护不排除基金自身债务的依法执行|第七条禁止非因基金自身债务的强制执行，不能反向解释为基金财产对自己承担的债务也绝对免责。|基金财产一经独立即免于所有执行|财产独立划分债务责任范围，不是将基金变成对自身合法债务无需清偿的主体。|所有执行均应改向管理人股东个人进行|基金自身债务原则上由基金财产承担，不能无依据改向管理公司股东个人追索。|只要基金还有投资者就不得执行|投资者存在不构成阻却基金自身债务依法执行的条件，持有人权利与债权人权利均受法律约束。
2.2.a|公私募收益风险分配规则区别|第三条第三款|讲师断言所有证券投资基金的收益与风险都必须严格按份额分配，基金合同绝不能作任何区别。按基金法如何纠正？|公募按份额享收益担风险，非公募由基金合同约定|基金法在公募和非公募之间明确区分分配与风险承担机制，不能把公募比例规则无区别推广。|公私募都可由管理人每年临时决定|非公募依合同而非临时决定，公募也有法定份额原则，不能把两类都变成管理人任意安排。|公募的分配必须依管理公司股权比例|管理公司股权与基金份额不同，公募持有人享有收益和承担风险的基础不是管理公司的股份。|非公募基金合同只可规定固定保底收益|合同约定分配不代表可违规保本保收益，更不意味着非公募合同只能采用固定收益模式。
4.1.c|基金税收承担与代扣代缴区分|第八条|依法应对基金财产投资相关税款代扣代缴时，管理人认为税由持有人承担，自己便不需办理扣缴。应怎样理解？|税负承担与扣缴义务不同，仍须按税收规定履行扣缴|基金法区分持有人承担相关税收与管理人或其他扣缴义务人的代扣代缴职责，不能相互替代。|税由持有人承担就一律免除机构扣缴|最终税负归属不决定机构是否承担法定扣缴义务，应依税收征收规定识别办理主体。|代扣代缴意味着税款必须由管理人固有财产承担|扣缴是依法办理税款征收的职责，不等于管理人当然成为最终税负承担者。|基金财产独立就可以不考虑任何税收|财产独立不构成普遍免税依据，基金投资涉及的具体税收仍应按国家相关规定执行。
4.1.a|非基金管理公司开展公募业务的准入|第十二条第二款|一家其他金融机构称自己不是基金管理公司，因此可跳过核准直接管理公募基金。准确判断是什么？|其他机构须经证券监管机构按规定核准后方可担任|基金法允许合规的其他机构担任公募管理人，但明确核准条件，不能把非基金公司身份当作免审通道。|任何金融机构持营业执照即可管理公募|一般营业资格不等于公募基金管理资格，开展特定受托业务仍须满足专门准入要求。|公募管理人只能是名称含基金的公司|法律明确存在经核准的其他机构路径，不能把名称或公司类别作为唯一许可渠道。|聘用一位已获资格基金经理就等同机构核准|个人从业资格与机构业务资格分属不同层次，人才聘用不能替代管理机构获准。
4.1.d|专业人士持股计划的制度许可|第二十一条第二款|公募管理公司拟依法设计专业人士持股计划，反对者称从业人员不得持有管理公司股权，长期激励一律违法。仅按基金法应怎样认识？|法律允许实行专业人士持股计划以建立长效激励约束|基金法明确允许这一治理安排，具体实施仍须满足适用规则，不能将个人证券投资限制泛化成一律禁止。|法律允许意味着无需任何公司治理或资格审查|原则许可不等于免除具体实施要求，股权激励仍须在适用治理和监管框架内办理。|只允许发现金奖金，绝不允许专业人士持股|该说法与第二十一条明示的持股计划安排相反，混淆了长效激励的合法方式。|持股后个人利益自动等同全部基金持有人利益|股权激励有助长期约束但不会消除所有冲突，仍需遵循基金持有人利益优先及相应制度。
4.3.a|管理与托管的股权隔离|第三十五条|一家公募基金管理公司拟少量参股其基金托管人，认为不取得控制权便不影响独立性。该理由是否成立？|不成立，管理人与托管人不得相互出资或持股|法定限制不仅针对控制权，少数股权也属于相互出资或者持股，不能以比例较小排除适用。|成立，只有交叉控股才受限制|第三十五条没有把限制收窄到交叉控股，直接以是否控制作为判断标准遗漏了禁止持股要求。|成立，只要托管费保持市场水平|托管费公允不能替代机构及股权独立要求，收费水平与相互持股是否合法是不同事项。|经基金经理同意就可以参股|基金经理不具有豁免法定独立性要求的权力，内部同意不能使禁止安排合法化。
4.3.b|托管账户的分设义务|第三十六条第三项|同一银行托管两只基金，拟共用证券账户、只在内部台账记明归属以节省成本。怎样评价？|应分别设置账户确保财产完整和独立|法律要求对不同基金财产分别设置账户，内部台账不能当然替代账户层面的分设。|只需每季度核对内部台账|季度核对不能补足不同基金账户未分设的问题，核对频率和财产独立是不同控制要求。|只要两基金管理人相同即可共用|管理人相同不消灭不同基金财产边界，各基金持有人并不因此成为同一资产池。|托管行资本充足即可共用|银行自身资本水平不能改变受托基金的独立财产性质，也不能替代法定分设账户义务。
4.3.b|净值复核与投资决策边界|第三十六条第八项、第十项|管理人称托管人已复核基金净值，所以某笔投资失败应完全由托管人承担。哪项分析最恰当？|净值复核不等于接管投资决策或担保投资结果|托管复核是独立职责，不能据此推导投资管理责任转移或托管人保证每笔投资获利。|复核后全部投资责任转为托管责任|净值计算审查与组合投资决策分工不同，完成复核不构成投资责任全面转移的依据。|托管人只保管现金，不需复核净值|法条明确要求托管人复核、审查净值和申赎价格，不能以保管职责否认其他法定职责。|发生亏损就说明净值复核一定错误|市场价格下跌可以造成真实亏损，投资结果不佳本身不能证明净值计算或复核有误。
5.1.a|持有人依法自行召集大会的前提|第八十三条第二款|代表12%基金份额的持有人就同一事项要求开会，日常机构、管理人、托管人均不召集。按基金法，持有人可怎样行动？|符合前提的持有人可自行召集并报监管备案|达到10%以上份额且法定召集主体均不召集时有自行召集路径，还应按规定向监管备案。|只能等待管理人改变主意，不能自行召集|法律已为相应份额持有人提供治理救济，不能因管理人不行动就使大会永远无法召开。|任意一个持有人任何时候均能跳过召集顺序|自行召集有份额比例、同一事项和前序主体不召集等条件，不能从特定救济推广为无限权限。|自行召集后就不需会议公告及表决程序|取得召集资格并不免除大会其他法定程序，公告、参加份额和表决等要求仍应履行。
4.1.b|管理职责终止后的业务资料交接|第二十九条第二款|原公募管理人已被解任，因与新管理人存在管理费争议，拟扣留基金交易记录。正确处理是什么？|妥善保管并及时移交，费用争议另行解决|职责终止后仍有保管和移交义务，不能将保障基金连续运作的资料作为追讨争议费用的筹码。|新管理人先支付争议费用才移交|基金资料交接不能被任意附加清偿争议款项的条件，否则会影响持有人权益和连续管理。|只交最新净值即可|最新净值不能替代完整业务资料，投资、会计和合规记录均关系到新管理人实际承接职责。|因已解任而销毁旧记录|职责终止并不等于记录保存义务结束，销毁会直接妨碍依法保管和及时移交。
4.1.b|管理人职责终止审计的对象|第三十条|公募基金更换管理人，旧管理人仅提供自身公司财务审计，声称足以满足交接审计。应纠正哪一点？|应按规定审计基金财产并公告、备案结果|第三十条的审计对象是基金财产，不是管理公司的固有财务报表，且还要求公告和备案。|管理公司财务审计涵盖所有受托财产|受托基金财产独立于公司财产，公司报表审计不能当然覆盖或替代基金财产的专项要求。|只要新管理人同意即可不审计|新管理人同意不能免除职责终止时的法定审计程序，持有人权益也不只涉及接收方。|仅向原管理人股东提供审计结果|审计结果需依法公告并备案，不是仅供原管理公司股东了解公司情况的内部材料。
4.1.a|公募管理公司资本形式|第十三条第二项|拟设公募基金管理公司申报一亿元注册资本，其中一半为估值专利、一半为认缴现金。仅就基金法资本条件，问题在哪里？|资本须达到法定下限且为实缴货币资本|金额达到一亿元并不充分，基金法对公募基金管理公司还明确了实缴与货币两项条件。|专利估值足够高就可替代货币|资本形式有专门限制，不能只核算总估值而忽略必须采用实缴货币资本的法定条件。|认缴承诺与实缴资本完全等同|承诺出资尚未形成实际缴付，基金法特别要求实缴，不能仅用未来缴款计划满足要求。|只需取得营业执照，资本形式不再审查|设立登记与公募管理准入并不相互替代，取得营业执照不豁免基金法规定的资本条件。
2.2.b|持有人查阅公开披露资料|第四十六条第二款|基金客服只允许大额投资者复制已公开的公募基金报告，小额持有人仅可听电话摘要。应如何调整？|所有公募持有人均有权查阅或复制公开披露资料|法律把此项权利赋予公募基金份额持有人，并没有按持有金额划分复制资料的资格。|保留门槛，因为复制权取决于投资规模|投资规模不构成剥夺法定查阅复制权的依据，小额份额同样对应法律保护的持有人身份。|只要电话摘要准确即可拒绝复制|电话说明不能替代法律明确赋予持有人的查阅或复制权，摘要也未必覆盖全部披露信息。|由管理公司股东会决定哪些人可复制|股东会不能改写基金持有人的法定权利范围，管理公司治理权限不包括任意设置该门槛。
5.1.a|持有人大会与日常机构权限区分|第四十七条、第四十八条|某公募持有人大会日常机构拟直接决定更换管理人，基金合同未授予额外职权。法定权限如何区分？|日常机构可提请更换，决定权由持有人大会行使|法律区分日常机构的提请权和大会的决定权，没有额外合同授权时不能把两种权限混为一谈。|日常机构成立后自动替代大会全部职权|设立日常机构是为了履行列明职责，并非让大会全部权力无条件转移给少数日常机构成员。|只有管理公司董事会可以更换管理人|管理公司的董事会不是基金持有人的决策机关，基金管理人更换属于基金治理事项。|托管人发一份通知即可完成更换|托管人可能依法承担召集等职责，但通知本身不能替代持有人大会依法作出的更换决定。
4.1.f|风险准备金的计提来源|第二十二条第一款|公募管理公司拟从基金认购本金直接额外划款计提自身风险准备金，称最终可赔偿持有人。应如何修正？|依法从管理基金的报酬中计提风险准备金|基金法规定的计提来源是管理基金的报酬，不能因准备金有保护作用就擅自额外扣取认购本金。|保护持有人的用途使任何扣款来源都合法|使用目的正当不等于资金来源可任意安排，仍应遵守法定计提来源和费用边界。|只在发生赔偿案件后才需建立准备金|风险准备金应依法计提，不能把事前制度建设推迟到损失及赔偿责任发生以后。|准备金只能由托管人股东出资提供|第二十二条针对公募管理人规定从管理报酬中计提，并未将该责任转给托管人的股东。
5.1.b|公募注册前预售的边界|第五十条、第五十五条|公募基金注册申请尚未获准，销售人员准备以可退款的预售名义收取认购款并锁定份额。应如何判断？|注册后方可发售，退款约定不能替代准予注册|预售安排已经涉及基金份额发售，基金法要求募集申请经注册后方可发售，不能靠可退款规避。|可退款就不属于任何募集行为|是否可以退款不能当然改变收款锁定基金份额的实质，发售前置注册要求仍需满足。|已提交申请等同获准注册|提交申请只是进入审查程序，并不代表监管机关已经作出准予注册的决定。|销售机构承诺承担损失即可预售|销售机构担责承诺无法替代法定注册条件，也不能赋予其提前发售基金份额的权限。
5.1.b|延后募集且实质变更的程序|第五十七条第一款|公募基金获准注册七个月后才准备发售，投资范围已发生实质变化。管理人只拟报送备案。应怎样修正？|重新提交注册申请|超过六个月开始募集且原注册事项发生实质变化，应重新申请注册，不能只按无实质变化情形备案。|只需补交延迟说明|延期说明不能替代因实质变化而要求的重新注册程序，时间与内容变化都需要同时判断。|沿用原注册无须任何程序|原注册针对原申请事项，超过规定期间并有实质变化时，不能无条件沿用。|先募集成功再申请重新注册|先募集后注册颠倒了法定程序，重新申请的要求应在依变化后的方案募集前落实。
5.1.c|基金份额上市申请的受理主体|第六十一条|基金已完成公开募集，管理人准备申请份额上市，却把上市申请只交给基金业协会。应向哪个主体申请？|向证券交易所申请，经其依法审核同意签订上市协议|基金份额上市与管理人登记或基金备案不同，基金法规定上市申请交交易所，审核同意后签上市协议。|向基金业协会备案即完成上市申请|协会登记备案职责不等同交易所上市审核，不能用一个业务程序替代另一个市场准入程序。|由托管银行自行决定挂牌并通知交易所|托管银行不是决定基金上市交易的法定主体，其保管职责不能替代交易所审核。|只要管理人公告交易代码就能上市|管理人自己公告代码并不能产生交易所上市资格，仍须完成法定申请及协议程序。
5.1.c|基金份额终止上市的决定与备案|第六十四条|某上市基金合同期限届满，业务员认为只能由证监会先作出终止上市决定、交易所再执行。准确区分是什么？|由证券交易所终止上市交易，并报监管机构备案|法条把终止上市决定安排给交易所，并要求报监管备案，不能把备案关系误写为逐案前置决定。|由基金销售机构决定终止上市|销售机构管理销售业务，不具有代替证券交易所作出基金份额终止上市决定的法定权限。|期满后管理人可不经任何程序继续交易|合同期限届满属于法定终止上市情形，不能由管理人忽略交易所规则继续维持原交易状态。|终止上市必等于所有持有人立即按面值获偿|上市资格变化不是保本兑付承诺，后续权利和财产处理仍须依基金合同及法律规则进行。
5.1.a|公募管理托管报酬标准的决定权|第四十七条第四项|基金合同要求由持有人大会处理报酬标准调整，管理人和托管人私下签补充协议提高两项费率。哪项正确？|应由持有人大会依法决定调整报酬标准|基金法列明大会有调整管理人托管人报酬标准的职权，本题合同也明确要求，双方私约不能替代。|收费双方达成一致便可约束持有人|基金财产承担费用，收费方之间一致不等于获得持有人治理机关的有效决定。|管理人股东会通过即可代替基金大会|管理公司股东会与基金持有人大会属于不同利益主体的决策机关，不能相互替代权限。|只要新增费用用于改善服务就无需履行程序|用途可能正当但不能豁免约定及法定治理程序，服务改善不等于持有人已经批准调费。
5.1.c|赎回延期事由消失后的处理|第六十七条第二款、第三款|因交易场所依法临时停市无法计算净值，管理人已按规定备案延期支付；停市原因现已消失。应怎样继续？|及时支付赎回款项|合法延期情形消失后应及时支付，原延期备案不等于获得无限延长付款期限的权限。|继续等待下一个季度统一支付|延期事由已经消失，不能自行将付款推迟到季度末而脱离及时支付的法定要求。|要求投资者重新发起赎回才付款|原赎回并未因延期当然失效，管理人不能无依据把自己的支付义务改为投资者重新申请。|以停市期间市场下跌为由永久取消赎回|市场波动不能使已成立的赎回自动取消，合法延期与永久拒绝履约是不同概念。
5.1.c|净值小额错误也须纠正|第七十条|复核发现净值计价错误为0.2%，未达到基金法0.5%的公告备案门槛。经理拟因未达门槛而不纠正。应怎样做？|立即纠正并防止损失扩大，区分纠错与公告门槛|立即纠错适用于计价错误本身，0.5%是本条公告备案的触发标准，不是可以容忍错误的下限。|低于公告门槛就可保留错误净值|把信息披露门槛错误理解为计算正确性要求的豁免，会使已知错误继续影响投资者。|等错误累计到0.5%才开始纠正|纠正义务不以累计达到公告标准为前提，等待会扩大错误价格对申购赎回的影响。|只需在下一期报告注释，现有净值不改|事后注释不能代替立即纠正和防止损失扩大的措施，披露与业务纠错应分别履行。
5.1.g|公募基金承担无限责任投资禁区|第七十三条第三项|公募基金拟作为普通合伙人投资一项项目，理由是预计只投入少量资金。仅按基金法该安排有什么问题？|基金财产不得从事承担无限责任的投资|判断关键是责任性质而非首期投入规模，普通合伙人可能承担超出出资的责任，触及禁止边界。|只要初始投入占净值很低即可|较低投资金额不能把无限责任改为有限责任，风险敞口并不当然受初始出资额限制。|合伙协议写明预计收益即可准入|收益预期与投资承担的法律责任不同，不能以盈利预测解除基金法的投资禁令。|取得被投企业承诺就消除无限责任|被投企业的承诺不能当然改变对外责任结构，仍须按基金实际承担的法律责任判断。
5.1.g|承销证券与认购投资区分|第七十三条第一项|基金经理计划让公募基金签署证券承销协议赚取承销费，称这与参与发行申购一样。怎样评价？|承销证券属于禁止活动，不能与合规认购投资混同|承销承担发行销售职责，基金申购证券属于投资，两者法律性质不同，不能因都发生于发行期而等同。|只要承销的是债券就可以|禁止承销证券并未仅针对股票，债券也属于证券，产品名称不能改变承销活动性质。|承销费归基金就不受限制|收益归属正确不代表投资活动本身合法，不能以增加基金收益取代业务范围限制。|发行人承诺回购即可视为普通认购|附加回购安排不能自动改变已签承销协议的法律性质，仍须识别实际承担的承销职责。
5.1.g|公募财产向管理人出资的禁止|第七十三条第五项|管理人拟增资扩充资本，让其所管公募基金直接认缴管理公司新增股权，称可享未来分红。应如何判断？|基金财产不得向基金管理人出资|直接向管理人出资触及法定禁止活动，不是只要披露利益冲突就可实施的普通关联证券交易。|只要董事会批准及披露即可认缴|对于明确禁止的向管理人出资，内部批准和信息披露不能替代或豁免禁止性规定。|持股比例不构成控制即可认缴|本条禁止并不以取得控制权为前提，少数股权同样可能构成向管理人出资。|未来分红归基金就不受禁止|收益归基金不改变出资对象被明确禁止的事实，不能以预期获利跳过投资范围审查。
5.1.h|涉及基金财产诉讼的披露识别|第七十六条第十项|基金作为原告主张重大财产权益，诉讼尚未判决。披露人员称没有结果便不属于基金应披露信息。正确认识是什么？|涉及基金财产的诉讼属于法定披露信息类别|是否形成终局结果不决定其是否属于该类信息，具体时点按适用披露规则履行，不能一概等判决。|仅败诉案件才进入披露范围|法条未把诉讼披露范围限制为败诉，胜败尚未确定也可能是投资者需要了解的重要信息。|只要不影响管理费就无须披露|披露关注基金财产及业务等事项，而不是只看是否影响管理人的收费收入。|可以用未经证实的胜诉预测替代事实披露|披露应区分已发生事实和不确定结果，胜诉预测不能替代真实准确的诉讼信息。
5.1.h|托管专门部门重大人事变动披露|第七十六条第九项|托管银行基金托管专门部门发生重大人事变动，管理人称银行不是基金公司所以不在基金披露范围。正确认识是什么？|法定披露信息包含托管专门部门重大人事变动|基金法并非只关注管理人一侧，托管专门部门的重大人事变化也被明确列入基金披露信息类别。|只有整家银行董事长变更才可能披露|法条具体覆盖托管专门部门重大人事变动，不能用银行整体层级限制排除该类别。|任何银行普通员工调岗均必须按同等标准披露|法条强调专门托管部门及重大人事变化，不能无区别扩展为银行所有员工的一般调岗。|只要基金净值未变化就无需披露此类事项|重大人事变动的法定类别并不以已发生净值波动为前提，治理风险信息不能只看当日价格。
5.1.f|风险提示不能洗白业绩预测|第五十六条第三款、第七十七条第二项|公募宣传页写明“预计未来一年回报12%”，页脚另写“不构成承诺”。如何评价？|免责声明不使证券投资业绩预测自动合规|基金法对公开披露和宣传推介中的投资业绩预测作出限制，加上非承诺字样不能改变预测内容。|写了不承诺即可随意预测收益率|预测和收益承诺是两个分别受限制的行为，否认承诺不代表已消除业绩预测问题。|只要历史一年收益达到12%即可预测|历史表现不能保证未来结果，也不能使被限制的未来业绩预测因参考历史而当然合法。|改成由销售人员口头预测就不受限制|口头宣传也须遵循合规要求，不能通过从纸面改为口头规避对募集宣传的行为约束。
3.3.a|基金协会权力机构与执行机构|第一百零九条|协会拟决定需由权力机构审议的事项，秘书处称全体员工会议可以代替会员大会。应怎样区分？|协会权力机构为全体会员组成的会员大会|协会法定权力机构以会员身份组成，不是日常秘书处员工会议；执行和服务团队不能当然替代。|协会权力机构由管理规模最大的五家会员组成|会员规模影响力不等于法律赋予少数机构替代全体会员大会的权力，成员构成应依法确定。|协会只接受监管领导，不需要会员大会|接受监管指导监督与具有法定会员治理结构并不冲突，不能因此取消会员大会。|由证券交易所董事会代行协会全部权力|证券交易所和基金协会是不同组织，前者董事会没有当然代行后者权力机构的权限。
5.1.i|封闭式基金延期的多条件审查|第七十九条|封闭式基金业绩良好且大会同意延期，但管理人一年前因违法受行政处罚。仅按基金法延期条件应怎样判断？|仍不满足管理人最近两年未受相关处罚的条件|业绩和持有人表决只是条件的一部分，最近两年未因违法违规受行政或刑事处罚也是法定要求。|大会同意即可豁免管理人处罚记录|持有人表决不能替代或豁免法定资格条件，须同时满足各项要求后履行相应程序。|只要缴清罚款就视为未受处罚|缴清罚款是履行处罚决定，不会把已发生的处罚从最近两年的事实记录中消除。|仅刑事处罚影响延期，行政处罚无关|第七十九条同时列明行政处罚和刑事处罚，不能自行将适用范围收窄为刑事处罚。
5.1.i|公募清算组的组成责任|第八十一条第一款、第二款|基金合同终止后，管理人想只委托自己的销售子公司组成清算组，托管人及中介均不参与。仅按基金法，应如何修正？|管理人组织清算组，由管理人、托管人及相关中介组成|法条明确组织责任和清算组组成，销售子公司不能单独取代基金管理人、托管人与相关中介的角色。|销售子公司可因客户最多而独占清算职权|掌握客户不构成替代法定清算组组成的依据，客户服务和基金财产清算是不同业务。|托管人可自行排除管理人组织清算|基金法将组织清算组责任赋予管理人，不能仅凭托管人保管资产而取消这一法定分工。|只要资产全是现金就无需清算组|财产形式简单不等于合同终止后无须依法组织清算，清理债权债务等职责仍须履行。
5.1.a|持有人大会重新召集的时间及范围|第八十六条第二款|首次公募持有人大会因出席份额不足未能召开。下列方案均拟采用重新召集时的三分之一出席份额门槛，其他程序符合要求。哪项符合基金法的重召时间和议题限制？|原定日后四个月，仍表决原定审议事项|首次不足后的重召应在原定召开时间三个月以后六个月以内，且限于原定事项；四个月及原议题同时满足两项条件。|原定日后两个月，仍表决原定审议事项|保持原议题只满足范围要求，两个月尚未进入三个月以后的重召期间，不能据此使用降低后的出席门槛。|原定日后五个月，同时增加一项新议题|五个月位于重召期间，但本条重召针对原定审议事项，不能借降低出席门槛同时增加新的表决事项。|原定日后八个月，仍表决原定审议事项|八个月已超出原定时间六个月以内的范围，即使议题不变，也不能按本条特定重新召集安排适用降低门槛。
5.1.a|公募通讯会议与代理出席|第八十五条|持有人长期在海外，管理人称只能本人到境内现场投票，不能采用通讯或委托代理。按基金法哪项判断正确？|法律允许通讯等方式召开，也允许委托代理人行权|基金法明确允许多种会议方式和代理出席，具体按适用规则及合同办理，不能一概排除。|通讯会议只允许管理公司股东参加|基金持有人大会与管理公司股东会不同，法律允许基金大会采用通讯方式并不依赖公司股东身份。|委托代理后基金份额所有权必然转移|代理是表决权行使方式，不等于基金份额转让，不能把授权参会误认为经济权利归属改变。|只有超过10%份额者才可委托代理|第八十五条的代理权没有该持仓门槛，10%与特定召集情形有关，不能移植到代理出席。
4.4.b|销售机构破产时结算资金隔离|第一百条第一款|销售平台破产，清算人拟以尚在划付中的基金销售结算资金偿还平台供应商。应怎样判断？|结算资金独立，不属于平台破产或清算财产|基金销售结算资金受到专门独立性保护，平台破产不使投资人的资金转为平台普通资产。|尚未划给基金就属于平台财产|划付过程中的占有并不改变受保护资金的性质，不能把暂存时间作为归入平台资产的依据。|供应商提供过技术服务即可优先拿走|平台供应商债权针对平台自身，不能据此越过结算资金独立性去清偿平台固有债务。|只保护现金购买的份额，不保护待划资金|第一百条同时保护销售结算资金和基金份额，不能只保留后者而遗漏尚在划付的资金。
4.4.b|销售结算资金被临时挪用|第一百条第二款|支付机构每天晚间将基金销售结算资金转入自营账户赚隔夜收益，次晨归还。其合规问题是什么？|短暂归还安排不改变挪用结算资金的性质|法律禁止任何形式挪用销售结算资金，隔夜时间短或按时归还都不能替代独立安全要求。|只要次晨归还就不属于挪用|是否归还影响后果但不当然改变未经允许转作自营用途的行为性质，短期挪用同样受禁。|收益分一半给投资者即可实施|收益分配方案不能授权支付机构挪用受保护的结算资金，更不能以潜在收益代替财产隔离。|只要支付机构有足额自有资金即可|有偿付能力不等于可动用投资人资金，机构资本与结算资金独立使用是不同要求。
`);

// Batch A2: separate partnership rights, default rules, liability and winding-up decisions.
rows('fund3','expansionGovPartnership',`
3.2.b|有限合伙的最低普通合伙人结构|第六十一条第二款|一家基金拟登记为有限合伙，全部出资人均约定只当LP，另聘咨询公司做投资。仅就合伙主体结构，应怎样调整？|至少应当有一名普通合伙人|有限合伙依法至少需要一名普通合伙人，外聘投资咨询服务不能替代组织法要求的合伙人身份。|咨询公司签服务协议即可代替GP|服务提供者不因签服务协议而成为普通合伙人，不能补足有限合伙组织的法定结构。|全部LP缴清出资即可不设GP|足额出资解决出资履行问题，不改变有限合伙必须至少有一个普通合伙人的组织要求。|基金只投少数股权即可不设GP|基金投资对象与自身组织形式是不同层次，少数股权投资不能豁免设立结构的法定要求。
3.2.b|上市公司不能担任普通合伙人|第三条|一家上市公司拟以GP身份发起股权基金，自称可以在内部章程中限制责任。应怎样评价？|上市公司不得成为普通合伙人|合伙企业法直接限制上市公司成为GP，内部责任限额不能改变该主体资格禁令。|上市公司股东大会批准即可担任GP|公司内部决议不能豁免法律对上市公司普通合伙人资格的限制，授权程序与主体适格应分别审查。|只要认缴额较小就可担任GP|普通合伙人的对外责任并不受认缴额限制，金额大小也不构成法定主体禁令的例外。|上市公司不得参与任何合伙基金|禁止成为GP不等于禁止作为合法的LP参与，不能把特定身份限制扩大为一切参与禁止。
4.4.f|合伙协议修改的默认同意规则|第十九条第二款|基金合伙协议未约定修改门槛，GP想以其认缴比例最大为由单独改变争议解决条款。应怎样处理？|按默认规则取得全体合伙人一致同意|在协议没有另行约定时，修改或补充合伙协议应全体一致，认缴最多不产生单方修约权。|GP认缴最多即有单独修约权|出资比例优势不等于可以绕过合伙协议的法定默认修改门槛，管理权与修约权不能混同。|所有LP合计过半同意即可修改|没有不同约定时应满足全体一致，而不是仅以LP群体内部过半替代全体合伙人的同意。|只要修改的是程序条款就不需同意|争议解决条款同样属于合伙协议内容，不能自行以程序性为由排除协议修改规则。
4.4.b|有限合伙人不得以劳务出资|第六十四条第二款|技术专家希望作为基金LP，以未来五年提供行业研究报告折抵认缴出资。仅按合伙企业法应如何判断？|LP不得以劳务出资，须另行设计合法出资和服务安排|未来提供研究服务属于劳务，有限合伙人出资规则明确排除此方式，服务价值不使其变成财产权出资。|全体合伙人评估劳务后LP即可出资|劳务评估约定不能豁免LP不得劳务出资的强制规则，不能照搬普通合伙人的出资方式。|研究服务价值足够就视为货币出资|服务估值不等于实际货币交付，财务折算不能改变劳务出资的法律属性。|LP不能提供服务，所以只能退出基金|不能以劳务履行出资不等于一律禁止其另行提供合法服务，须区分投资出资与服务关系。
4.4.b|LP未履行出资的双重责任|第六十五条|LP收到依约有效的缴款通知后未按期足额出资，愿付一笔违约金并声称此后无需补缴。怎样判断？|仍负补缴义务，并按约对其他合伙人承担违约责任|补缴出资和违约责任可以同时存在，支付违约金不当然解除尚未履行的认缴出资义务。|付违约金就必然替代所有认缴义务|违约责任与履行出资义务并不天然互斥，不能仅凭支付违约金推导认缴承诺已经消灭。|因为LP责任有限所以可以自由拒绝出资|责任有限以认缴额为边界，不意味着认缴后可以不履行缴款约定，有限责任与免除出资不同。|GP必须无条件用个人资金补足LP缺口|违约LP是补缴及违约责任主体，不能无合同法律依据把其出资义务全部移转给GP个人。
4.4.e|执行事务报酬的协议依据|第六十七条|GP已按合伙协议收取约定管理费，现拟因额外执行事务再提取一项未约定报酬。不存在法律另有规定或已生效协议变更。依合伙企业法，哪项做法合适？|先依合伙协议约定报酬及提取方式，再据此办理|法律允许执行事务合伙人要求在合伙协议中确定报酬及其提取方式，但该权利不等于可单方创设额外收费并直接划款。|由GP内部投资委员会决定金额，即可直接划取|内部投资委员会决定不能替代合伙协议对收费的有效约定，投资决策授权也不当然包含另设执行事务报酬的权力。|向LP发送一次收费通知，无须取得有效协议依据|单方通知说明拟收费事实，不自动构成有效的报酬及提取方式约定，不能据此将通知等同协议变更。|由托管人确认账户余额充足，即可提取该项报酬|托管人对余额或资金划付的操作确认不能创设GP收费权，资金足够不代表存在合法有效的费用约定。
3.2.b|有限合伙名称的法定标识|第六十二条|一家股权基金拟以有限合伙形式登记，却只在宣传材料注明有限合伙，不在企业名称中标明。仅按合伙企业法应怎样处理？|企业名称中应当标明有限合伙字样|法定标识要求针对企业名称，帮助识别组织和责任结构，宣传材料额外说明不能替代名称要求。|向全部投资者发邮件即可免去名称标识|投资者私下知情不等于其他交易相对人可以依法从企业名称识别组织类型，不能替代法定标识。|名称中只有投资基金四字即可满足标识|投资基金描述业务，不明确合伙责任结构，因此不能替代有限合伙这一法定组织形式标识。|只要GP承诺承担责任就可任意省略标识|GP责任承诺不能豁免企业名称的法定要求，责任安排与名称公示是互补而非替代关系。
3.2.b|执行事务人怠于行权时LP救济|第六十八条第七项|基金应收赔偿被GP长期搁置，LP为基金利益拟以自己名义提起诉讼。就LP行为性质而言，哪项正确？|符合法定情形的此类诉讼不视为执行合伙事务|执行事务人怠于行权时，法律允许LP督促或为企业利益以自己名义诉讼，不能一概认定越权经营。|LP只有退出基金才能保护权益|退出不是唯一救济，法律提供在存续期间督促行权和为企业利益诉讼的保护性途径。|LP起诉必然使其对基金全部债务无限负责|保护性诉讼属于明确例外，不因实施该行为就当然对所有基金债务承担普通合伙人责任。|LP必须把基金应收赔偿先买成个人债权|法定救济无需先将企业债权转让给LP，诉讼为企业利益而提起，不是必须转成个人追索。
8.3.b|LP向本企业提供担保的性质|第六十八条第八项|某有限合伙人仅以自己名义依法为本合伙基金的一笔债务提供有效担保，未参与经营决策，也未获其他事务授权。哪项关于合伙事务与责任的判断准确？|该担保不视为执行合伙事务，仍依担保关系承担责任|第六十八条将依法为本企业提供担保列为不视为执行事务的行为；这一分类并不消灭其有效担保产生的独立责任，两种关系应分开判断。|该行为不视为执行事务，因此担保责任仍以其认缴出资额封顶|有限合伙人对合伙债务的出资责任与其自愿另行承担的担保责任不同，不能用有限合伙出资上限缩减有效担保约定的责任范围。|对外承担担保责任就是代表基金经营，因此本次应按执行事务处理|担保人对债权人承担约定责任不等于代表基金执行合伙事务，法律对题设这种依法担保已列明不视为执行事务的例外。|该担保属于一般代理授权，签约后可据此代表基金处理其他债务|担保行为不等于获得基金事务的代理权，题设没有其他授权，不能从一笔担保推导出代表基金处理其他交易的权限。
8.3.c|LP关联交易的协议约束|第七十条；另须遵守基金监管规则|LP拟把一项资产卖给合伙基金，协议明确禁止LP与基金交易。其称合伙法原则允许所以可忽略协议。正确意见是什么？|应遵守协议限制，法条允许另行约定|合伙法的允许规则以协议未作相反约定为前提；基金关联交易监管要求也不能因此被排除。|法律原则允许便使所有禁止条款无效|第七十条明确保留协议另行约定，不能用默认允许规则推翻有效的更严格合同限制。|只要价格公允就无须考虑协议禁止|价格公允与是否有权实施交易是不同问题，公允报价不能自动豁免协议明确的交易限制。|向GP口头披露就视为修改协议|披露不等于修改合伙协议，变更限制还须满足有效的修约程序及其他适用监管要求。
8.3.c|LP同业竞争的默认规则与边界|第七十一条|LP同时投资一家与合伙企业竞争的企业，协议对此未作限制。仅按合伙企业法的身份规则，应怎样判断？|LP原则上可以，仍须核对其他适用法律与具体义务|有限合伙人的竞争业务有区别于普通合伙人的规则，协议未另约定时法条原则允许。|LP一律适用普通合伙人的绝对竞争禁止|普通合伙与有限合伙的事务参与及责任不同，不能把普通合伙人的规则不加区别地移植。|只要是LP便可泄露基金商业秘密支持竞争者|默认允许竞争不代表允许泄露秘密或损害合法权益，其他保密及监管义务仍须遵守。|LP投资竞争者后自动丧失全部基金份额|法律没有因该默认允许行为就自动没收份额的规定，不能凭竞争关系直接推导财产权消灭。
3.2.b|LP份额出质的协议例外|第七十二条|合伙协议禁止LP以基金份额出质，LP仍拟为个人借款办理质押。仅从合伙法规则看，应首先注意什么？|LP出质的原则许可受合伙协议另行约定约束|第七十二条允许份额出质但保留协议例外，不能只读原则许可而忽视已存在的合同限制。|LP份额任何情形都不得出质|法条不是一律禁止出质，而是在默认许可基础上允许协议另作约定，须结合具体条款判断。|个人借款与基金无关所以协议不适用|即使借款用途属个人，拟出质的仍是合伙财产份额，协议关于该份额的限制不能被忽略。|只要债权人不了解协议就不需审查|是否对外产生具体法律效果需要另行分析，不能因此免除LP在行动前遵守有效协议的义务。
9.6.c|LP对外转让的提前通知|第七十三条|LP按有效合伙协议向符合其他条件的外部投资者转让份额，拟在交割当天才告知其他合伙人。应怎样修正？|依法提前三十日通知其他合伙人|第七十三条对LP按协议对外转让另设提前三十日通知要求，不能以交割日通知替代。|只通知GP且不需提前即可|法律通知对象是其他合伙人，不能当然缩小为GP一个主体，也不能省略提前期限。|转让价格高于成本就可省略通知|通知义务不以转让是否获利为条件，价格高于成本不能豁免其他合伙人的程序保障。|外部受让人签署保密协议即可替代通知|保密承诺与通知原合伙人的义务目的不同，完成前者不能自动视为履行后者。
9.6.c|LP债权人执行份额时的优先权|第七十四条第二款|LP个人债权人依法申请法院执行其基金份额。其他合伙人愿按同等条件购买。应如何保障其权利？|法院应通知全体合伙人，同等条件下有优先购买权|强制执行并不当然排除其他合伙人的优先购买权，法律同时要求通知全体合伙人。|强制执行无需通知任何其他合伙人|第七十四条明确规定通知义务，不能以执行程序公权力性质为由排除合伙人的知情保障。|GP可不比较条件直接无偿取得|优先购买是同等条件下的购买权，不是GP无偿取得财产或无视报价条件的特权。|其他合伙人必须低价购买全部份额|法律赋予权利而非强制购买义务，也不授权其以低于同等条件的任意价格优先成交。
3.2.b|有限合伙仅剩LP的组织后果|第七十五条前段|基金唯一GP依法退出，此后仅剩LP，团队拟以有限合伙形式永久继续经营。按合伙法应怎样判断？|仅剩有限合伙人时应当解散|有限合伙不能在只剩LP的结构下继续作为该类企业永久经营，法条对仅剩LP规定了解散后果。|自动转为普通合伙且LP全部变GP|法条区分仅剩LP和仅剩GP的情形，不能把仅剩GP时转为普通合伙的规则反向套用。|只要LP人数超过十人就可继续|LP数量再多也不补足普通合伙人缺位，人数与必要合伙人类型是两项不同要求。|由托管人自动成为GP|托管关系不自动产生普通合伙人身份，托管机构不能因GP退出而依法当然接替其角色。
3.2.b|有限合伙仅剩GP的组织后果|第七十五条后段|一只有限合伙基金的LP全部退出，存续者均为普通合伙人。仅按合伙企业法的组织形式规则，应如何处理？|转为普通合伙企业|仅剩普通合伙人与仅剩有限合伙人的后果不同，前者转为普通合伙，而非当然维持有限合伙形式。|继续保留有限合伙名称即可|组织名称不能替代真实合伙人结构，已无LP时不能仅靠名称维持有限合伙身份。|普通合伙人自动全部变成LP|法律没有规定这种自动身份反转，GP承担责任的基础不会因LP退出而自行变成有限责任。|只要管理人仍在就无需处理组织形式|管理人存续与基金合伙人结构是不同问题，管理服务不能替代组织形式的依法调整。
3.2.b|LP造成普通合伙人外观的交易责任|第七十六条第一款|LP对外以GP身份签约，交易对方有充分理由相信其为GP并与其交易。该LP对这笔交易承担何种责任？|对该笔交易承担与普通合伙人同样的责任|法条保护有理由相信其为GP的交易相对人，责任针对该笔交易，不能仅用内部LP身份对抗。|始终仅以已实缴出资为限|这遗漏表见普通合伙人的特别责任，也将通常的认缴责任边界误写成已实缴金额。|自动对基金历史及未来全部债务无限负责|第七十六条表述针对该笔交易，不能无条件扩大为对所有过去未来债务的身份转换。|只有实际参与投资盈利才承担责任|责任触发于有理由相信身份并实施交易等条件，不以是否分享具体交易利润为前提。
8.3.c|LP越权交易的内部赔偿|第七十六条第二款|LP未经授权以基金名义订购服务，给基金造成损失；相对人知道其无权代表。至少应如何看待LP对基金的责任？|LP应对其越权行为造成的损失承担赔偿责任|即使题设不满足第三人有理由相信其为GP的条件，未经授权交易造成损失仍可触发内部赔偿责任。|相对人知道无权就免除LP所有责任|外部交易效力与LP给基金造成损失的内部赔偿是不同问题，不能因相对人知情就一并免除。|LP有限责任使其任何侵害均只承担认缴额|有限责任不是个人违法或越权行为的全面免责条款，对其自身致损行为仍需依法负责。|损失必须由没有参与签约的其他LP平摊|不能以基金内部损失分担取代对越权致损者的追责，其他LP并非当然替其承担个人赔偿责任。
4.4.b|新LP对入伙前债务的责任|第七十七条|新投资者以LP身份入伙，发现基金存在入伙前债务，便主张“这些债务与我完全无关”。正确判断是什么？|对入伙前债务以认缴出资额为限承担责任|新LP并非完全不受历史债务影响，但其责任依特别条款以认缴额为限，不等同新GP的无限责任。|新LP对入伙前债务一概零责任|法条明确把入伙前企业债务纳入其有限责任范围，不能仅凭入伙时间较晚完全排除。|新LP应对历史债务承担无限连带责任|无限连带责任是普通合伙人的规则，新LP有明确特别规定，不能把两种身份混为一谈。|只要债权人没出席入伙会议就无责任|债权人是否出席入伙会议不是法定责任边界，不能将内部会议参与情况当作免责条件。
9.6.a|LP丧失民事行为能力后的资格|第七十九条|自然人LP因意外丧失民事行为能力，其他合伙人仅以此为由要求其退伙。应怎样判断？|不得仅因此要求该LP退伙|合伙法对自然人LP作特别保护，丧失民事行为能力本身不使其他合伙人取得强制退伙权。|与普通合伙人规则相同，必须立即退伙|LP不执行事务，法律对其资格连续性作出特别规定，不能直接照搬普通合伙人的处理。|资格立即转为其监护人个人所有|监护代理和财产所有权不同，LP丧失行为能力不使其基金权益自动转移给监护人。|基金必须立即全体清算|单个LP出现这一情况不是全体基金必须清算的法定当然事由，组织可依法处理代理和权利行使。
9.6.a|LP死亡后的资格承受|第八十条|自然人LP死亡，继承人拟依法承受其基金权益及LP资格，GP称死亡后该份额必然归GP。正确看法是什么？|继承人可以依法取得该LP资格|法律允许继承人依法承受有限合伙人资格，不能因死亡把其财产份额无偿归给GP。|LP死亡必使其出资转为无主财产|死亡触发继承或权利承受问题，不会使依法存在的财产权当然成为无主财产。|继承人只要承受份额就必须变成GP|承受有限合伙人资格并不要求改为普通合伙人，责任身份不能被GP单方提高。|GP可以因管理方便任意取消份额|基金管理便利不构成剥夺继承财产权的法律依据，仍须依法律及有效约定处理。
9.6.a|退伙LP的历史债务责任财产|第八十一条|LP退伙后，基金因退伙前已经发生的事项被确认一笔债务。该LP以已退出为由拒绝承担任何责任。哪项正确？|以退伙时从企业取回的财产承担该类债务责任|对基于退伙前原因发生的债务，退伙LP仍有法定责任，但边界是退伙时取回的财产。|退出后对一切历史事项立即免责|法律关注债务发生的基础原因是否在退伙前，不能仅以形式退出时间切断相关责任。|退伙LP必须以全部个人财产承担无限责任|这把退出LP的特别有限责任与GP责任混同，法条明确限定为退伙时取回的财产。|只在退伙当天已取得判决的债务才负责|法条关注退伙前的原因，不是判决作出日期，之后确认债务也可能属于该责任范围。
8.3.c|GP与LP转换的默认同意门槛|第八十二条|合伙协议未约定身份转换规则，一名LP欲自行登记变成GP，认为多承担责任无须别人同意。正确处理是什么？|应经全体合伙人一致同意|身份转换影响执行事务及整体治理结构，未作相反约定时须全体一致，并非个人承担更多责任即可单方完成。|申请人签承诺书即可单方转换|个人承诺不能替代合伙法设置的默认同意程序，身份转换会改变其他合伙人的关系和权利。|只需取得原GP同意|协议未另约定时要求全体一致，不能将其他LP排除在身份转换的决定程序之外。|身份转换一律不被法律允许|法律明确规定GP和LP相互转换的程序与责任，不能把需要同意误解为完全禁止转换。
3.2.b|LP转GP后的既往债务责任|第八十三条|LP经合法程序转为GP后，基金债权人追索其原为LP期间发生的债务。新GP能否继续按旧LP责任限额抗辩？|不能，对原为LP期间发生的企业债务承担无限连带责任|身份转换后，法律明确扩大其对该历史期间债务的责任，不能仅凭原身份维持旧限额。|可以，责任永远按债务形成时身份冻结|第八十三条对LP转GP设有特别规则，不能用一般时间直觉忽略法定历史债务责任。|只对自己批准过的历史交易无限负责|法条并未将责任限于其个人批准的交易，转换后的历史企业债务责任不能如此任意缩减。|只要债权人没有反对转换即可免责|债权人没有反对不等于放弃债权或法定责任，不能把沉默推定为豁免历史债务。
3.2.b|GP转LP不能追溯消除无限责任|第八十四条|GP转为LP后主张，其过去作为GP期间的债务应随身份变化降为有限责任。哪项判断正确？|对原为GP期间发生的债务仍承担无限连带责任|身份转换不追溯削弱既往债权人的保障，法律保留其在普通合伙人期间形成债务的无限责任。|所有历史债务自动改按当前认缴额封顶|当前身份不能自动重写过去债务的责任安排，否则将使债权人保护取决于债务人单方重组。|变更登记公告满三十天即可消除旧责任|公告和等待时间并非法条规定的历史责任消灭条件，不能自行创设时效式免责门槛。|只要其他LP同意即可约束历史债权人|合伙人内部同意不能当然减损外部债权人的既有权利，内部安排与对外责任应分别识别。
9.6.e|清算人未及时确定时的救济|第八十六条第三款|合伙基金解散事由出现超过十五日，合伙人持续争执，未能确定清算人。应考虑哪项法定途径？|合伙人或其他利害关系人可申请法院指定清算人|法律提供法院指定途径以避免无人清算的僵局，申请资格不只属于执行事务合伙人。|只能无限期等待全体合伙人达成一致|法律已规定在期限内未确定清算人时的救济，不能把一致协商当作唯一永久路径。|由投资金额最大的LP自动任清算人|出资最大不是法定自动任命条件，指定清算人仍应依法律规定的程序进行。|由托管行直接注销基金组织|托管职责不等于清算人或登记机关权限，不能跳过确定清算人及清算程序直接注销。
9.6.e|清算期间禁止无关新经营|第八十八条第三款|合伙基金已进入清算，清算人认为企业尚未注销，打算新设项目公司开展全新业务。应怎样判断？|企业虽存续，但不得开展与清算无关的经营活动|清算期间存续是为了处理未了事项及债权债务，不能把尚未注销解释为可继续开拓无关新业务。|营业执照未注销就可无条件开新项目|形式存续不等于正常经营权限不受限制，清算状态对经营范围具有特别约束。|只要新项目可能盈利就可以实施|盈利预期不能替代与清算相关性的判断，新增风险可能妨碍债权清偿和退出分配。|所有活动包括追收旧债都必须停止|禁止的是与清算无关经营，清理债权债务等正是清算职责，不能把限制扩大为一切行动停止。
9.6.e|合伙基金清算剩余财产的前置清偿|第八十九条|合伙基金出售最后一个项目收到现金，尚有职工工资、税款及外部债务未处理，GP拟先向LP返还本金。应如何处理？|先依法支付清算费用等并清偿债务，再分配剩余财产|合伙人的剩余分配居于法定清偿之后，返还本金的名称不能使其越过职工、税款及债权人。|返还出资本金可以优先于全部债务|股权或合伙出资并非天然优先债权，不能用本金措辞改变清算中的法定清偿与剩余分配顺序。|只要LP全体同意就可先行分配|全体LP内部同意不能损害外部债权人及其他法定权利人，不能据此排除清算顺序要求。|将未清偿债务写进附注即可分完现金|披露债务不能替代清偿或依法妥善处理债务，先分光财产仍会影响债权人保障。
9.1.c|合伙注销后的原GP债务责任|第九十一条|合伙基金完成注销，随后发现存续期间遗留债务。原GP称登记注销证明一切责任结束。正确看法是什么？|原GP对存续期间债务仍承担无限连带责任|组织注销与原普通合伙人的责任消灭并不同步，法律明确保留其对企业存续债务的无限责任。|注销证书等同债权人免债证明|登记注销不是债权人的债务豁免，也不当然消灭依法应由原GP承担的遗留债务责任。|只由原LP按人数平均清偿|不能把原GP的法定无限连带责任转给无相应责任基础的LP，更不能任意按人数分摊。|只有注销前已起诉债务才有效|第九十一条关注债务形成于存续期间，不以是否已经起诉作为责任继续存在的条件。
9.6.e|合伙破产不免除GP责任|第九十二条第二款|合伙基金已依法被宣告破产，GP认为企业进入破产即可像公司股东一样免除超出出资的责任。哪项正确？|GP对合伙企业债务仍应承担无限连带责任|合伙破产程序不改变普通合伙人法定无限责任，不能照搬一般公司股东有限责任模式。|企业破产自动把GP变成有限责任股东|基金的组织形式和合伙人责任不会因破产自动变成公司股东模式，法律明确保留责任。|GP只补足尚未实缴部分即可免责|普通合伙人的责任不以认缴或实缴额为上限，仅补出资不能当然清偿其全部对外责任。|由破产管理人个人承接全部旧债|管理人承担程序管理职责，不因接管破产事务而成为替代GP的全部债务承担人。
9.1.a|合伙企业成立日期的识别|第十一条|合伙协议周一签署、周三提交申请、周五营业执照签发，下周一首次投资。组织法上的成立日期是哪天？|周五营业执照签发日|合伙法以营业执照签发日期作为企业成立日期，协议生效、申请受理和首次经营是不同节点。|周一协议签署日|合伙协议的效力与合伙企业主体成立应区分，签署协议本身不能代替取得营业执照。|周三申请提交日|递交材料只是登记申请行为，并不代表登记机关已经作出登记决定并签发营业执照。|下周一首笔投资日|开始业务不是企业成立的法定标志，已依法成立的企业也可能尚未进行任何投资。
4.4.f|非货币出资的权属转移手续|第十七条第二款|合伙企业接受一项依法需要转移登记的知识产权出资，出资人只交了估值报告，未办权属转移。应补足什么？|依法办理相应财产权转移手续|估值解决出资作价问题，不能替代法律要求的权属转移，两项程序有不同目的。|估值报告盖章就视为所有转移完成|专业估值确认价值不等同权属登记完成，不能以估值文件代替法律规定的财产权变动手续。|出资人保证不再使用即可无需过户|个人不使用的承诺不等于企业依法取得产权，仍应依适用规定完成必要转移程序。|只要全体合伙人认可价值即可免去手续|合伙人对价值的内部认可不能豁免法定产权转移要求，内部约定与对外权属效力不同。
2.4.d|普通合伙未约定一般表决规则|第三十条；题设为普通合伙且无特别表决事项|股权投资管理人采用普通合伙形式，一般内部事项未约定表决办法，也不属于法定特殊事项。甲出资70%便称独自通过。应如何判断？|默认一人一票，并经全体合伙人过半数通过|普通合伙的一般默认规则以合伙人人数而非出资比例计票，本题明确排除法定特别事项。|按认缴比例过半便自然通过|出资比例可依约设计但不是该场景的法定默认规则，不能在协议沉默时自行套用。|默认任何事项均须全体一致|部分事项有一致要求，但一般事项的默认规则是人数过半，不能把特别门槛泛化。|由执行事务合伙人永久享有全部表决权|执行事务授权不当然消灭其他合伙人的决议权，仍应依协议或法定表决规则办理。
2.4.d|事务执行内部限制与善意第三人|第三十七条|普通合伙管理人内部限制执行合伙人签约金额，但其超额签约的相对人确属善意。能否仅凭内部限额对抗相对人？|不能以该内部限制对抗善意第三人|合伙法区分内部权限约束和外部善意交易保护，仍可另行追究违反内部授权者的责任。|可以，未达到内部审批就必然对外无效|内部审批缺失不当然击破善意第三人的交易保护，不能把内部合规问题直接等同对外无效。|不能对抗便意味着执行人无任何内部责任|外部交易受保护不等于内部越权免除，内部追责与对外效力是两个法律层次。|只要企业事后亏损即可认定相对人非善意|亏损不等于相对人知道权限限制，善意判断应看相关认知和事实，而非交易结果。
4.4.f|普通合伙利润分配默认顺序|第三十三条第一款；题设为普通合伙|普通合伙基金未约定利润分配，合伙人协商不成，但实缴出资比例可明确确定。下一步应按什么分配？|按照实缴出资比例分配|默认顺序是在协议及协商均不能解决时按实缴比例，无法确定该比例才进入平均分配。|立即按合伙人人数平均分配|平均分配是无法确定出资比例时的后续规则，本题已有明确实缴比例，不能跳过。|由GP按贡献印象自行决定|执行事务身份不赋予绕过法定默认顺序的任意分配权，主观贡献判断不能替代有效规则。|只按认缴比例而不看实际缴付|法条在该默认层次采用实缴出资比例，认缴和实缴不同，不能无约定将两者替换。
2.4.d|普通合伙全部亏损集中承担限制|第三十三条第二款；题设为普通合伙|普通合伙型管理人拟约定全部亏损都由一名小合伙人承担，其余合伙人永不承担亏损。应如何评价？|普通合伙协议不得约定由部分合伙人承担全部亏损|本条对普通合伙内部损失分担作出明确限制，不能将所有亏损排他性转给某一部分合伙人。|只要被分配亏损者签字就当然有效|自愿签字不能当然排除强制限制，协议自治也须处于法律允许的范围内。|只要该合伙人同时领取工资即可有效|工资和劳动报酬关系不能自动豁免合伙法的亏损分担限制，两类利益安排应分别审查。|内部约定一经成立也可免除外部无限连带责任|即便内部合法分担约定，也不能当然对抗外部债权人的无限连带责任请求。
2.1.c|新普通合伙人的历史债务责任|第四十四条第二款|股权管理企业为普通合伙，新GP入伙时约定只参与未来项目。对外部既存企业债务，哪项判断正确？|新GP对入伙前企业债务承担无限连带责任|内部只参与未来项目的安排不能当然排除新普通合伙人对既存企业债务的法定对外责任。|项目参与范围等同于对外债务范围|业务分工与对外法定责任不同，未参与历史项目不代表无需承担入伙前企业债务。|只要未获历史收益便无历史债务责任|法定责任并不以新合伙人是否分得历史利润为前提，收益分配安排不能简单替代债务规则。|新GP只以入伙首日现金出资负责|普通合伙人承担无限连带责任，并非以首日实缴现金封顶，不能套用LP责任结构。
9.6.a|普通合伙退伙结算中的未了事项|第五十一条第二款|普通合伙人退伙时，一项应收赔偿仍在诉讼且尚未了结。其要求立即按自己估计额分走现金。应怎样处理该未了事项？|待该事务了结后进行相应结算|法律对退伙时未了结事务明确了结后结算，不能以退出方单方估计代替实际处理。|退伙人单方预测即可拘束其他合伙人|未了事务有真实不确定性，单方估计并非依法完成结算的充分依据，也不当然拘束他人。|该未了事务自退伙日起自动归GP个人|退伙不使企业权利变为执行事务人的个人财产，应依法处理并确定退伙结算。|只要未了事项有风险就可永久没收份额|等待事项了结不是永久剥夺财产权，事务明确后仍应按有效规则完成结算和返还。
9.6.a|退伙返还的货币与实物方式|第五十二条|合伙人退伙，协议有效约定返还部分现金和依法可交付的实物财产。退出方称法律只允许现金。正确理解是什么？|返还方式可依协议或全体决定采用货币或实物|合伙法允许货币或实物返还，题设已有有效协议，不能将法律误读为一律只准现金。|所有实物返还都违法|法律明确容许实物返还，但具体资产交付仍需满足权属、监管及有效约定等要求。|GP可以无视协议任意挑选最差资产返还|容许实物不等于授权任意挑选或违反协议，返还方式和作价仍应依有效安排公平执行。|实物交付后无需考虑必要产权手续|返还方式允许实物并不排除具体资产的产权转移手续，法律允许方式与交付完成应分开判断。
9.6.a|普通合伙退伙的历史原因债务|第五十三条|GP依法退伙后，一项基于其退伙前合同形成的合伙企业债务才到期。债权人未免除其责任，退伙结算也未改变对外债务。原GP承担责任的正确判断是什么？|仍对该债务承担无限连带责任|合伙企业法以退伙前原因形成的债务为责任边界，不能仅因到期日晚于退伙日排除原GP的无限连带责任。|只以退伙时实际取回的财产价值为限承担责任|这是对原普通合伙人责任范围的错误缩减，题设基于退伙前原因形成的债务仍适用无限连带责任。|仅当债务在退伙前已到期时才承担责任|责任判断看债务形成原因而不单看到期日，尚未到期不代表合同基础在退伙前不存在。|只要后任GP承诺负责，原GP即不再对外承担责任|内部承接或后任承诺未获债权人免除原责任的效力，不能单方削弱债权人对原GP的法定追索权。
8.3.c|侵占合伙利益的返还与赔偿|第九十六条|执行合伙人把应属于基金的一笔交易补偿转入个人账户，后称只要赔基金损失即可保留补偿。应怎样处理？|应返还该利益和财产，造成损失还须依法赔偿|返还不当取得利益与赔偿额外损失可以并行，不能选择只赔部分损失而继续保留基金财产。|只要个人账户余额未减少就未侵占|占用并改变应归企业利益的归属不以消费完毕为前提，账户仍有余额不消除返还义务。|基金没有最终亏损就不必返还补偿|该款本来应归企业，返还不以最终账面亏损为必要条件，不能把财产权与损害结果混淆。|经其个人财务顾问确认就可转作个人收入|个人顾问的意见不能授权其取得企业利益，应按财产归属与法定忠实义务处理。
`);

